const body = $json.body ?? {};
const context_id = body.from;
const message = String(body.body ?? '').trim();

return [{
  json: {
    context_id,
    message,
    waitSeconds: 6,
  },
}];

const raw = $json.buffer ?? [];
const entries = (Array.isArray(raw) ? raw : [raw])
  .map((entry) => {
    if (!entry) return null;
    if (typeof entry !== 'string') return entry;
    try {
      return JSON.parse(entry);
    } catch {
      return { text: entry, timestamp: new Date().toISOString() };
    }
  })
  .filter(Boolean)
  .sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));

const message = entries
  .map((entry) => String(entry.text ?? '').trim())
  .filter(Boolean)
  .join('\n');

return [{
  json: {
    context_id: $('Preparar Mensaje').item.json.context_id,
    message: message || $('Preparar Mensaje').item.json.message,
  },
}];

