const analysisRaw = String($json.output || '').trim();
const contextId = $('Consolidar Buffer').item.json.context_id;
const customerMessage = String($('Consolidar Buffer').item.json.message || '');

function parseAnalysis(raw) {
  const fallback = {
    wantsHuman: false,
    knowsModel: false,
    canAccessPhone: true,
    canIdentifyFailure: false,
    issueType: 'unknown',
    model: '',
    brand: ''
  };

  if (!raw) return fallback;

  let payload = raw;
  const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced?.[1]) payload = fenced[1].trim();

  try {
    const parsed = JSON.parse(payload);
    return {
      wantsHuman: parsed.wantsHuman === true,
      knowsModel: parsed.knowsModel === true,
      canAccessPhone: parsed.canAccessPhone !== false,
      canIdentifyFailure: parsed.canIdentifyFailure === true,
      issueType: ['screen', 'other', 'unknown'].includes(parsed.issueType) ? parsed.issueType : 'unknown',
      model: String(parsed.model || '').trim(),
      brand: String(parsed.brand || '').trim()
    };
  } catch {
    return fallback;
  }
}

const analysis = parseAnalysis(analysisRaw);

const API_BASE = process.env.N8N_PUBLIC_API_BASE_URL || process.env.API_BASE_URL || 'http://api:3000/api/v1/n8n';

async function getTemplate(key) {
  const url = `${API_BASE}/message-templates/${encodeURIComponent(key)}`;
  const response = await fetch(url);
  if (!response.ok) return '';
  const data = await response.json();
  return String(data.text || '').trim();
}

function applyTemplate(text, values) {
  return Object.entries(values).reduce((acc, [k, v]) => {
    const safeValue = String(v ?? '');
    return acc.replace(new RegExp(`{{\s*${k}\s*}}`, 'g'), safeValue);
  }, text);
}

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

const msgNorm = normalize(customerMessage);
const hasScreenHint = /(pantalla|display|lcd|tactil|touch|cristal|vidrio)/.test(msgNorm);
const hasNoAccessHint = /(no\s+prende|no\s+enciende|no\s+puedo\s+acceder|no\s+puedo\s+usar|no\s+tengo\s+el\s+telefono|no\s+tengo\s+el\s+celular)/.test(msgNorm);

if (hasNoAccessHint) analysis.canAccessPhone = false;
if (hasScreenHint && analysis.issueType === 'unknown') analysis.issueType = 'screen';

const wantsHumanByText = /(humano|asesor|agente|persona|ejecutivo|representante)/.test(msgNorm) && /(hablar|comunicar|pasar|transfer)/.test(msgNorm);
if (wantsHumanByText) analysis.wantsHuman = true;

async function searchSupplier(model, supplier) {
  const url = `${API_BASE}/products/search?model=${encodeURIComponent(model)}&supplier=${encodeURIComponent(supplier)}`;
  const response = await fetch(url);
  if (!response.ok) return [];
  const items = await response.json();
  return Array.isArray(items) ? items : [];
}

function pickScreenItem(items) {
  const includeTerms = ['pantalla', 'display', 'lcd', 'touch', 'tactil', 'oled', 'amoled'];
  const excludeTerms = ['bateria', 'battery', 'pila'];

  const scored = items.map((item) => {
    const text = normalize(`${item.brand || ''} ${item.model || ''}`);
    const includes = includeTerms.some((t) => text.includes(t));
    const excludes = excludeTerms.some((t) => text.includes(t));
    return { item, score: includes ? 2 : 1, excludes };
  });

  const filtered = scored.filter((x) => !x.excludes);
  const pool = filtered.length ? filtered : scored;

  if (!pool.length) return null;

  pool.sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    return Number(a.item.price || 0) - Number(b.item.price || 0);
  });

  return pool[0].item;
}

async function searchExternalPrice(url) {
  try {
    const response = await fetch(url, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (compatible; n8n-bot/1.0)'
      }
    });

    if (!response.ok) return null;

    const html = await response.text();
    const match = html.match(/\$\s?[0-9][0-9.,]{2,}/);
    if (!match) return null;

    return match[0].replace(/\s+/g, '');
  } catch {
    return null;
  }
}

async function buildReply() {
  if (analysis.wantsHuman) {
    const tpl = await getTemplate('transferencia_humano');
    return {
      reply: tpl,
      transferToHuman: true
    };
  }

  if (!analysis.canAccessPhone || !analysis.knowsModel || !analysis.model) {
    const tpl = await getTemplate('diagnostico_sin_acceso') || await getTemplate('diagnostico_gratuito');
    return { reply: tpl, transferToHuman: false };
  }

  if (analysis.issueType !== 'screen') {
    const tpl = await getTemplate('diagnostico_no_pantalla') || await getTemplate('diagnostico_gratuito');
    return { reply: tpl, transferToHuman: false };
  }

  const model = analysis.model;

  const tecnomaxItems = await searchSupplier(model, 'tecnomax');
  const tecnomaxScreen = pickScreenItem(tecnomaxItems);
  if (tecnomaxScreen) {
    const tpl = await getTemplate('cotizacion_pantalla_proveedor') || await getTemplate('cotizacion_pantalla');
    return {
      reply: applyTemplate(tpl, {
        marca: tecnomaxScreen.brand || analysis.brand || '',
        modelo: tecnomaxScreen.model || model,
        precio: Number(tecnomaxScreen.price || 0).toFixed(2),
        proveedor: tecnomaxScreen.supplier || 'Tecnomax'
      }),
      transferToHuman: false
    };
  }

  const mnItems = await searchSupplier(model, 'mn refacciones');
  const mnScreen = pickScreenItem(mnItems);
  if (mnScreen) {
    const tpl = await getTemplate('cotizacion_pantalla_proveedor') || await getTemplate('cotizacion_pantalla');
    return {
      reply: applyTemplate(tpl, {
        marca: mnScreen.brand || analysis.brand || '',
        modelo: mnScreen.model || model,
        precio: Number(mnScreen.price || 0).toFixed(2),
        proveedor: mnScreen.supplier || 'MN Refacciones'
      }),
      transferToHuman: false
    };
  }

  const fixoemUrl = `https://www.fixoem.com/search?q=${encodeURIComponent(`${model} pantalla`)}`;
  const fixoemPrice = await searchExternalPrice(fixoemUrl);
  if (fixoemPrice) {
    const tpl = await getTemplate('cotizacion_fixoem');
    return {
      reply: applyTemplate(tpl, {
        modelo: model,
        precio: fixoemPrice,
        url: fixoemUrl
      }),
      transferToHuman: false
    };
  }

  const mlUrl = `https://listado.mercadolibre.com.mx/${encodeURIComponent(`${model} pantalla`)}`;
  const mlPrice = await searchExternalPrice(mlUrl);
  if (mlPrice) {
    const tpl = await getTemplate('cotizacion_mercadolibre');
    return {
      reply: applyTemplate(tpl, {
        modelo: model,
        precio: mlPrice,
        url: mlUrl
      }),
      transferToHuman: false
    };
  }

  const tpl = await getTemplate('sin_existencia_proveedores') || await getTemplate('diagnostico_gratuito');
  return {
    reply: applyTemplate(tpl, { modelo: model }),
    transferToHuman: false
  };
}

const result = await buildReply();

return [{
  json: {
    context_id: contextId,
    reply: result.reply,
    transferToHuman: result.transferToHuman
  }
}];

